CREATE TABLE IF NOT EXISTS runtime_lease (id INTEGER PRIMARY KEY CHECK(id=1), instance_id TEXT NOT NULL, boot_id TEXT NOT NULL, run_id TEXT NOT NULL, expires INTEGER NOT NULL, seen INTEGER NOT NULL, health TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS runtime_requests (id TEXT PRIMARY KEY, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS runtime_monitor (id INTEGER PRIMARY KEY CHECK(id=1), checked INTEGER NOT NULL);
